public class Main {
    public static void main(String[] args) {
        // 자동 형변환 (작은 거 -> 큰 거)
        int small = 10;
        double big = small; // OK
        System.out.println(big);

        // 강제 형변환 (큰 거 -> 작은 거)
        double pi = 3.99;
        int n = (int) pi; // 0.99 손실 발생!
        System.out.println(n);

        // char also acts like int
        int code = (int) 'A';
        System.out.println(code);
    }
}
